    skSolve(s1);
    extrude(context, id + "floor", { "bodyType" : ExtendedToolBodyType.SURFACE, "surfaceEntities" : qOwnedByBody(qBodyType(qCreatedBy(id + "s1", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "endBound" : BoundingType.BLIND, "depth" : 4 * millimeter, "oppositeDirection" : false });
    const s2 = newSketchOnPlane(context, id + "s2", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(s2, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(30, 0) * millimeter });
    skSolve(s2);
    extrude(context, id + "wall", { "bodyType" : ExtendedToolBodyType.SURFACE, "surfaceEntities" : qOwnedByBody(qBodyType(qCreatedBy(id + "s2", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "endBound" : BoundingType.BLIND, "depth" : 20 * millimeter, "oppositeDirection" : true });
    faceBlend(context, id + "blend1", { "side1" : qOwnedByBody(qBodyType(qCreatedBy(id + "floor", EntityType.BODY), BodyType.SHEET), EntityType.FACE), "flipSide1" : true, "side2" : qOwnedByBody(qBodyType(qCreatedBy(id + "wall", EntityType.BODY), BodyType.SHEET), EntityType.FACE), "flipSide2" : false, "radius" : 5 * millimeter, "propagation" : false, "crossSection" : FaceBlendCrossSection.ROLLING_BALL, "blendControlType" : BlendControlType.RADIUS, "asymmetric" : false, "crossSectionShape" : FaceBlendCrossSectionShape.CIRCULAR, "tangentHoldLines" : false, "conicHoldLines" : true, "hasCliffEdges" : false, "hasCaps" : false, "hasLimits" : false, "hasHelpPoint" : false, "trim" : FaceBlendTrimType.WALLS, "detach" : false, "showSelection" : false, "showIsocurves" : false, "conicEdges" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "floor", EntityType.BODY), BodyType.SHEET), EntityType.EDGE), vector(15, 0, 4) * millimeter), "inverseConicEdges" : qNothing() });
