// loft: a circle of radius 10 to a 20 mm square 20 mm above, the circle's vertex at (10, 0) connected to the corner at (10, 10)
export function c003(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(s1, "c1", { "center" : vector(0, 0) * millimeter, "radius" : 10 * millimeter });
    skSolve(s1);
    const s2 = newSketchOnPlane(context, id + "s2", { "sketchPlane" : plane(vector(0, 0, 20) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(s2, "r1", { "firstCorner" : vector(-10, -10) * millimeter, "secondCorner" : vector(10, 10) * millimeter });
    skSolve(s2);
    loft(context, id + "loft1", { "sheetProfilesArray" : [{ "sheetProfileEntities" : qSketchRegion(id + "s1") }, { "sheetProfileEntities" : qSketchRegion(id + "s2") }], "matchConnections" : true, "connections" : [{ "connectionEntities" : qUnion([qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "s1", EntityType.BODY), BodyType.SHEET), EntityType.VERTEX), vector(10, 0, 0) * millimeter), qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "s2", EntityType.BODY), BodyType.SHEET), EntityType.VERTEX), vector(10, 10, 20) * millimeter)]), "connectionEdgeQueries" : qNothing(), "connectionEdgeParameters" : [] }] });
